"@import url('https://fonts.googleapis.com/css2?family=Roboto+Mono:wght@400;700&family=Ubuntu+Mono:wght@400;700&display=swap');

body {
  margin: 0;
  padding: 10px;
  background-color: #0b0d10; /* Deep Carbon Black */
  color: #e2e8f0; /* Brushed Silver */
  font-family: 'Ubuntu Mono', monospace;
  font-size: 13px;
  user-select: none;
}

/* Header Banner */
.banner {
  border-bottom: 2px solid #232a35;
  padding-bottom: 8px;
  margin-bottom: 12px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.banner-title {
  font-family: 'Roboto Mono', monospace;
  font-size: 14px;
  font-weight: bold;
  color: #bfa15f; /* Gold accent */
  letter-spacing: 1.5px;
}

/* Status Badge */
.status-container {
  display: flex;
  align-items: center;
  gap: 6px;
}
.status-dot {
  width: 8px;
  height: 8px;
  background-color: #7f8c8d;
  border-radius: 50%;
  transition: all 0.3s ease;
}
.status-dot.active {
  background-color: #00e676; /* Green */
  box-shadow: 0 0 10px #00e676;
  animation: pulse 1.5s infinite;
}
.status-dot.rapid {
  background-color: #d35400; /* Rapid copper alert */
  box-shadow: 0 0 10px #d35400;
  animation: pulse 0.6s infinite;
}
.status-dot.error {
  background-color: #ff1744;
  box-shadow: 0 0 10px #ff1744;
}

@keyframes pulse {
  0% { opacity: 0.4; }
  50% { opacity: 1; }
  100% { opacity: 0.4; }
}

