    lastSendTime = Date.now();
    stats.framesSent++;
    stats.lastSendTimestamp = new Date().toISOString();
    stats.nextSendIn = SEND_INTERVAL_MS;

    // Send to background worker for server POST
    chrome.runtime.sendMessage({
      action: "send-frame",
      dataUrl: frame.dataUrl
    }).catch(() => {});
  }"

