"/* Status Badge */
.status-container {
  display: flex;
  align-items: center;
  gap: 6px;
}
.status-dot {
  width: 8px;
  height: 8px;
  background-color: #7f8c8d;
  border-radius: 50%;
  transition: all 0.3s ease;
}
.status-dot.active {
  background-color: #00e676; /* Green */
  box-shadow: 0 0 10px #00e676;
  animation: pulse 1.5s infinite;
}
.status-dot.rapid {
  background-color: #d35400; /* Rapid copper alert */
  box-shadow: 0 0 10px #d35400;
  animation: pulse 0.6s infinite;
}
.status-dot.rest {
  background-color: #00bcd4; /* Rest Mode cyan */
  box-shadow: 0 0 10px #00bcd4;
  animation: pulse 2.5s infinite;
}
.status-dot.error {
  background-color: #ff1744;
  box-shadow: 0 0 10px #ff1744;
}

@keyframes pulse {
  0% { opacity: 0.4; }
  50% { opacity: 1; }
  100% { opacity: 0.4; }
}

